<script setup lang="ts">import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{listSiteConfig,updateSiteConfig,type SiteConfigItem}from'../../api/siteConfig';const items=ref<SiteConfigItem[]>([]),saving=ref('');const asConfig=(row:unknown)=>row as SiteConfigItem;onMounted(refresh);async function refresh(){items.value=await listSiteConfig()}async function save(item:SiteConfigItem){saving.value=item.key;try{await updateSiteConfig(item.key,item.value);ElMessage.success('网站配置已保存')}catch(e){ElMessage.error(e instanceof Error?e.message:'保存失败')}finally{saving.value=''}} </script><template><main class="admin-shell"><header class="page-header"><div><p class="eyebrow">站点级配置</p><h1>网站配置管理</h1><p class="subtitle">只维护系统预定义的网站公共配置项，不提供任意配置键。</p></div></header><el-card shadow="never"><el-table :data="items"><el-table-column prop="description" label="配置项" width="220"/><el-table-column prop="key" label="Key" width="210"/><el-table-column label="配置值"><template #default="s"><el-input v-model="s.row.value" :type="s.row.valueType==='JSON'?'textarea':'text'"/></template></el-table-column><el-table-column label="操作" width="110"><template #default="s"><el-button type="primary" link :loading="saving===s.row.key" @click="save(asConfig(s.row))">保存</el-button></template></el-table-column></el-table></el-card></main></template>
